// ───────────────────────────────────────────────────────────────
// MODULE: Skill Doc Frontmatter Harvest
// ───────────────────────────────────────────────────────────────
// Parses the canonical reference/asset frontmatter contract
// (title, description, trigger_phrases, importance_tier, contextType)
// so per-doc trigger phrases can feed advisor routing as doc-level
// signal. The advisor is these files' only runtime consumer.

// ───────────────────────────────────────────────────────────────────
// 1. IMPORTS
// ───────────────────────────────────────────────────────────────────

import { readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';

import { parseFrontmatter as parseFrontmatterBlock } from '@spec-kit/shared/frontmatter/parse-frontmatter.js';

// ───────────────────────────────────────────────────────────────────
// 2. TYPE DEFINITIONS
// ───────────────────────────────────────────────────────────────────

export interface ParsedDocFrontmatter {
  readonly title: string;
  readonly description: string;
  readonly triggerPhrases: readonly string[];
  readonly importanceTier: string;
  readonly contextType: string;
}

// ───────────────────────────────────────────────────────────────────
---
// ───────────────────────────────────────────────────────────────
// MODULE: Skill Metadata Sanitizer
// ───────────────────────────────────────────────────────────────

import { dirname, isAbsolute, relative, resolve, sep } from 'node:path';

type JsonRecord = Record<string, unknown>;

export const SKILL_METADATA_SANITIZER_VERSION = 'skill-metadata-boundary:v1';

const MAX_METADATA_VALUE_LENGTH = 512;
const CONTROL_CHAR_PATTERN = /[\u0000-\u001F\u007F]/u;
const INSTRUCTION_SHAPED_PATTERN = /\b(ignore|disregard|override|forget)\b.{0,48}\b(instructions?|rules?|policy|policies|system|developer)\b|\b(system|developer)\s+(prompt|message|instructions?)\b|\b(prompt injection|jailbreak|do not obey|reveal secrets?)\b/i;

function workspaceRootForSource(sourcePath: string): string {
  const resolved = resolve(sourcePath);
  const markers = [`${sep}.skilled${sep}skills${sep}`, `${sep}.opencode${sep}skills${sep}`];
  const index = Math.max(...markers.map((marker) => resolved.indexOf(marker)));
  if (index >= 0) return resolved.slice(0, index);
  return dirname(dirname(sourcePath));
}

function isInside(candidate: string, root: string): boolean {
  const rel = relative(root, candidate);
  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel));
}

function hasTraversal(value: string): boolean {
  return value.split(/[\\/]+/u).some((segment) => segment === '..');
}

